import { expect, test } from "bun:test";
import { exportMap, keysFor } from "../src";

test.each([
	["asIs", ["foo-bar_baz"]],
	["camelCase", ["foo-bar_baz", "fooBarBaz"]],
	["camelCaseOnly", ["fooBarBaz"]],
	["dashes", ["foo-bar_baz", "fooBar_baz"]],
	["dashesOnly", ["fooBar_baz"]],
] as const)("%s", (convention, keys) => {
	expect(keysFor("foo-bar_baz", convention)).toEqual([...keys]);
});

// Expected values generated by running css-loader v7.1.5's camelCase / dashesCamelCase.
test.each([
	["FooBar", "fooBar", "FooBar"],
	["BTN-primary", "btnPrimary", "BTNPrimary"],
	["btn-Primary", "btnPrimary", "btnPrimary"],
	["XMLHttpRequest", "xmlHttpRequest", "XMLHttpRequest"],
	["A", "a", "A"],
	["col-2-md", "col2Md", "col2Md"],
	["foo2bar", "foo2Bar", "foo2bar"],
	["2col", "2Col", "2col"],
	["h1Title", "h1Title", "h1Title"],
	["-foo", "foo", "Foo"],
	["--foo", "foo", "Foo"],
	["_bar", "bar", "_bar"],
	["foo--bar", "fooBar", "fooBar"],
	["foo__bar", "fooBar", "foo__bar"],
	["foo-_-bar", "fooBar", "foo_Bar"],
	["foo-", "foo", "foo-"],
	["é-à", "éÀ", "é-à"],
	["__", "", "__"],
] as const)("%s → camel %p, dashes %p", (name, camel, dashes) => {
	expect(keysFor(name, "camelCaseOnly")).toEqual([camel]);
	expect(keysFor(name, "camelCase")).toEqual(name === camel ? [name] : [name, camel]);
	expect(keysFor(name, "dashesOnly")).toEqual([dashes]);
	expect(keysFor(name, "dashes")).toEqual(name === dashes ? [name] : [name, dashes]);
	expect(keysFor(name, "asIs")).toEqual([name]);
});

test("exportMap maps keys back to class names", () => {
	const map = exportMap(["a-b", "c"], "camelCase");
	expect(Object.fromEntries(map)).toEqual({ "a-b": "a-b", aB: "a-b", c: "c" });
});
